import {WORK_LABELS} from './work-log.js?v=0.7.3-map1';
import {workshopCard} from './workshop-ui.js?v=0.7.3-map1';
import {workshopHours} from './workshop.js?v=0.7.3-map1';
import {cafeHours,clockLabel} from './game-time.js?v=0.7.3-map1';
import {deadlineView,contractById} from './contracts.js?v=0.7.3-map1';
import {LOCATIONS,euro} from './data.js?v=0.7.3-map1';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function workdayPanel(s,button,view='today'){
 const l=s.workLog??{entries:[],days:[]},day=l.days.find(d=>d.day===s.day),w=workshopHours(s),c=cafeHours(s),job=s.job,deadline=deadlineView(s);
 const live=[];
 if(s.workshop.active)live.push(`<article class="workday-active"><span class="eyebrow">DEINE WERKSTATTARBEIT</span>${workshopCard(s,button,true)}${button('Werkstatt markieren','navigate','deliveryWorkshop','secondary')}</article>`);
 if(job){const name=job.contract?contractById(job.contract).name:WORK_LABELS[job.type],target=LOCATIONS.find(p=>p.id===job.target);live.push(`<article class="workday-active"><span class="eyebrow">LAUFENDER AUFTRAG</span><h3>${name}</h3><p>${job.type==='courier'?job.interaction?.kind==='pickup'?'Pakete werden bei Kiez & Kurier übernommen.':'Nächster Halt: '+esc(target?.name??'Kiez & Kurier'):job.type==='cleaning'?`${job.progress} / 6 Abfallsäcke eingesammelt`:`${job.progress} / 4 Kisten einsortiert`}</p>${deadline?`<p class="${deadline.late?'routine-warning':'positive'}">${esc(deadline.text)} · ${esc(deadline.label)}</p>`:job.contract&&contractById(job.contract).minutes?'<p>Die Bonusfrist beginnt nach der Paketübernahme.</p>':'<p>Ohne Zeitlimit.</p>'}<div class="button-row">${button('Zum nächsten Ziel','trackJob','','primary')}${job.type==='courier'?button('Stoppliste & Abrechnung','tour','','secondary'):''}</div></article>`);}
 if(s.cafe?.phase==='open')live.push(`<article class="workday-active"><span class="eyebrow">CAFÉ MORGEN · IN BETRIEB</span><h3>${s.cafe.served} Gäste bedient</h3><p>${esc(c.detail)} · ${s.cafe.lost} Gäste verloren</p><p>Die Café-Kasse ist noch nicht abgerechnet. Sie zählt nicht zum ausgezahlten Auftragslohn.</p>${button('Zum Café','navigate','cafe','secondary')}</article>`);
 const entries=l.entries.filter(e=>view==='all'||e.day===s.day);
 return `<div class="workday"><div class="workday-top"><div><span class="eyebrow">TAG ${s.day} · ${clockLabel(s.minute)} · ${s.settings.speed}×</span><h3>Dein Arbeitstag</h3><p>Aufgaben planen. Fristen im Blick behalten.</p></div><div class="workday-earned"><span>Heute ausgezahlter Auftragslohn</span><strong>${euro(day?.paid??0)}</strong><small>${day?.settled??0} bezahlte Abrechnungen · ${day?.unpaid??0} ohne Lohn</small></div></div><h3 class="section-title">Laufende Aufgaben</h3>${live.length?live.join(''):`<div class="workday-empty"><strong>Kein Auftrag offen.</strong><p>Wähle eine Arbeit, für die heute noch genug Zeit bleibt.</p>${button('Aufträge ansehen','jobs','','primary')}</div>`}<h3 class="section-title">Zeiten & nächste Möglichkeiten</h3><div class="workday-hours"><article><span class="eyebrow">WERKSTATT WEST</span><h4>${w.accept?'Auftragsannahme offen':w.open?'Nur laufende Arbeiten abschließen':'Geschlossen'}</h4><p>08:00–19:00 · neue Aufträge bis 17:00</p><small>${w.accept?`${Math.max(0,4-(s.workshop.day===s.day?s.workshop.taken:0))} Tagesplätze übrig · noch ${Math.ceil(1020-s.minute)} Spielmin. bis Annahmeschluss`:w.open?'Abnahme heute bis 19:00':s.minute<480?'Heute ab 08:00 geöffnet':'Morgen ab 08:00 geöffnet'}</small>${button('Weg markieren','navigate','deliveryWorkshop','secondary')}</article><article><span class="eyebrow">CAFÉ MORGEN</span><h4>${s.businesses.cafe?esc(c.state):'Noch nicht dein Betrieb'}</h4><p>08:00–20:00 · Schichtbeginn bis 18:00</p><small>${s.businesses.cafe?esc(c.detail):'Übernahme und Betrieb verwaltest du unter Unternehmen.'}</small>${button(s.businesses.cafe?'Betrieb ansehen':'Unternehmen ansehen','businesses','','secondary')}</article></div><div class="workday-receipt-head"><h3 class="section-title">Deine Abrechnungen</h3><div class="button-row" aria-label="Abrechnungen filtern">${button('Heute','workday','today',view==='today'?'active':'secondary')}${button('Verlauf','workday','all',view==='all'?'active':'secondary')}</div></div><div class="workday-receipts">${entries.length?entries.map(e=>`<details><summary><span><b>${WORK_LABELS[e.type]}</b><small>Tag ${e.day} · ${clockLabel(e.minute)} · ${e.status==='paid'?e.late?'Bezahlt · verspätet':'Bezahlt':e.status==='expired'?'Frist verstrichen':'Zurückgegeben'}</small></span><strong class="${e.total?'positive':'muted'}">${euro(e.total)}</strong><span aria-hidden="true">⌄</span></summary><dl><div><dt>Grundlohn</dt><dd>${euro(e.base)}</dd></div><div><dt>Bonus</dt><dd>+ ${euro(e.bonus)}</dd></div><div><dt>Abzüge</dt><dd>− ${euro(e.deduction)}</dd></div><div><dt>Erfasste Dauer</dt><dd>${e.minutes} Spielmin.</dd></div></dl></details>`).join(''):'<p class="workday-empty">Noch keine Abrechnungen in dieser Ansicht. Neue Arbeiten werden ab Version 0.7.2 hier erfasst.</p>'}</div>${view==='all'&&l.days.length?`<h3 class="section-title">Letzte Arbeitstage</h3><div class="workday-days">${l.days.map(d=>`<div><span>Tag ${d.day}<small>${d.settled} bezahlt · ${d.unpaid} ohne Lohn</small></span><strong>${euro(d.paid)}</strong></div>`).join('')}</div>`:''}<p class="footnote">Die letzten 40 Arbeitsbelege und sieben Arbeitstage werden gespeichert. Auftragslohn ist kein Nettogewinn: Einkäufe, Weiterbildung, Fahrtkosten und Unternehmensbilanzen findest du unter Finanzen bzw. Unternehmen. Frühere Auszahlungen werden nicht nachträglich rekonstruiert.</p></div>`;
}
